#include <stdio.h>

void valid_seq(int a,int arr[],int sum,int check)
{
    if(sum==a)
    {
        for(int i=0;i<check;i++)
        {
            printf("%d \n",arr[i]);
        }

    return;    
    }
    int count=1;
    while(count<=(a-sum)&&(check==0||count<=arr[check-1]))
    {
        arr[check]=count;
        valid_seq(a,arr,sum+count,check+1);
        count++;
    }
} 
    void print_seq(int a)
    {
        int *arr;
        arr=(int*)malloc(a*sizeof(int));
        valid_seq(a,arr,0,0);

    }


int main(){
    int x;
    scanf("%d",&x);
    print_seq(x);
	return 0;
}

#include <stdio.h>


void check_seq(int num,int array[],int sum,int check)
{ if(sum==num)
   {
       for(int i=0;i<check;i++)
       {
           printf("%d",array[i]);
       }
       printf("\n");
       return;
   }
    int fing=1;
    while(fing<=num-sum&&(check==0||fing<=array[check-1]))
    {
        array[check]=fing;
        check_seq(num,array,sum+fing,check+1);
        fing++;
    }
}

void print_seq(int num)
{
    int *array;
    array=(int*)malloc(num*sizeof(int));
    check_seq(num,array,0,0);


}



