#include <stdio.h>
#include<stdlib.h>

void print(int * t,int position,int sum,int n)
{

    if(sum>n)
    return;
    if(sum==n)
    {
        for(int i=0;i<position;i++)
        printf("%d",t[i]);
        printf("\n");
        return ;
    }

    if(position!=0)
    {
        for(int i=0;i<=t[position-1];i++)
        {
            t[position]=i;
            print(t,position+1,sum+i,n);
        }
    }
    if(position==0)
    {
        for(int i=1;i<=n;i++)
        {
            t[position]=i;
            print(t,position+1,sum+i,n);
        }
    }
}
