    int n;
void print_seq(int*p,int place,int sum_p)
{
    if(sum_p==n)
    {
        for(int i=0;i<=place;i++)
        {
            printf("%d ",p[i]);
        }
        printf("\n");
        return;
    }
    if(sum_p>n)
    {
        return;
    }
    else
    {
        if(place==0)
        {
            for(int i=1;i<=n;i++)//p[0] ranges from 1 to n
            {
                p[place]=i;
                print_seq(p,place+1,sum_p+p[place]);
            }
        }
        if(place)
        {
            for(int j=1;j<=p[place-1];j++)
            {
                p[place]=j;
                print_seq(p,place+1,sum_p+p[place]);
            }
        }
    }
}
