#include <stdio.h>
int n;
int sum(int *arr,int top)
{
    int i,sum=0;
    for(i=0;i<=top;i++)
    sum+=arr[i];
    return sum;
}

void xyz(int *arr,int top)
{
    int i;
    int rsum=n-sum(arr,top);
    if(rsum==0)
    {
        for(i=0;i<=top;i++)
        printf("%d",arr[i]);
        printf("\n");
       return;
    }
  for(i=1;i<=arr[top];i++)
  {
      if(rsum-i<0)
      break;
      else
      {
          arr[top+1]=i;
          xyz(arr,top+1);
      }
  }
}

int main(){
    scanf("%d",&n);
